// panic-sort-lab/src/main.rs
use rayon::prelude::*;
use std::panic;
use std::sync::atomic::{AtomicUsize, Ordering::Relaxed};

static DROPS: AtomicUsize = AtomicUsize::new(0);

/// 自带 Drop 计数的元素： panic 后每个元素必须恰好 drop 一次
#[derive(Clone, Eq, PartialEq, Ord, PartialOrd)]
struct Tracked(u32);

impl Drop for Tracked {
    fn drop(&mut self) {
        DROPS.fetch_add(1, Relaxed);
    }
}

fn main() {
    panic::set_hook(Box::new(|_| {})); // 静音

    let base: Vec<Tracked> = (0..5_000)
        .map(|i| Tracked((i * 2_654_435_761) % 101))
        .collect();

    // 第一遍：正常排序，统计比较次数
    let comparisons = AtomicUsize::new(0);
    let mut probe = base.clone();
    probe.par_sort_by(|a, b| {
        comparisons.fetch_add(1, Relaxed);
        a.cmp(b)
    });
    let total = comparisons.into_inner();

    // 第二遍：让 panic 点扫过整个排序过程（分 10 档）
    let step = total / 10;
    let mut countdown = total;
    loop {
        DROPS.store(0, Relaxed);
        let mut v = base.clone();
        let target = countdown;
        let n = AtomicUsize::new(0);
        let _ = panic::catch_unwind(panic::AssertUnwindSafe(move || {
            v.par_sort_by(|a, b| {
                if n.fetch_add(1, Relaxed) + 1 >= target {
                    panic!("comparator boom");
                }
                a.cmp(b)
            });
        }));
        let dropped = DROPS.load(Relaxed);
        assert_eq!(
            dropped, 5_000,
            "panic 点 {target}: 元素必须恰好各 drop 一次"
        );
        if countdown < step { break; }
        countdown -= step.max(1);
    }

    // 第三遍：池子还活着吗？
    let mut alive: Vec<u32> = (0..10_000).map(|i| (i * 7) % 1_009).collect();
    alive.par_sort();
    assert!(alive.windows(2).all(|w| w[0] <= w[1]));
    println!("所有 panic 点检查通过：无泄漏、无双重 drop，线程池未卡死");
}
```

